"use strict";(self.webpackChunkwiki_pt_br=self.webpackChunkwiki_pt_br||[]).push([["54108"],{37063(e){e.exports=JSON.parse('{"tag":{"label":"Jetson","permalink":"/pt-br/tags/jetson","allTagsPath":"/pt-br/tags","count":7,"items":[{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware e Uso de Interfaces da reComputer Robotics","description":"Este wiki fornece uma introdu\xe7\xe3o abrangente aos recursos de hardware e ao uso das interfaces da placa carrier reComputer Jetson Robotics J401. Ele abrange especifica\xe7\xf5es detalhadas, m\xf3dulos suportados, instru\xe7\xf5es de configura\xe7\xe3o e guias pr\xe1ticos para usar v\xe1rias interfaces, como expans\xe3o de c\xe2mera M.2, Ethernet, USB, CAN, UART, I2C e GMSL2, ajudando os usu\xe1rios a iniciar rapidamente o desenvolvimento em rob\xf3tica na plataforma J401.","permalink":"/pt-br/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics_J40/pt_reComputer_Robotics_Getting_Started","title":"Introdu\xe7\xe3o ao reComputer Robotics","description":"A reComputer Robotics J401 \xe9 uma placa carrier de borda de IA de alto desempenho projetada para aplica\xe7\xf5es avan\xe7adas de rob\xf3tica. Ela suporta m\xf3dulos NVIDIA Jetson Orin Nano e Orin NX nos modos Super/MAXN, oferecendo at\xe9 157 TOPS de poder de computa\xe7\xe3o de IA. A placa oferece amplas op\xe7\xf5es de conectividade, incluindo Ethernet Gigabit dupla, m\xfaltiplas portas USB 3.2, CAN, slots M.2 para m\xf3dulos 5G/Wi-Fi/BT e suporte opcional a c\xe2mera GMSL2. Pr\xe9-instalada com JetPack 6, garante uma implanta\xe7\xe3o perfeita para desenvolvimento em rob\xf3tica. O design robusto suporta ampla faixa de temperatura de opera\xe7\xe3o e inclui um dissipador de calor com ventilador pr\xe9-instalado. A configura\xe7\xe3o envolve gravar o sistema operacional JetPack em um SSD NVMe usando um PC host Ubuntu compat\xedvel, seguida de configura\xe7\xe3o de hardware e uso das interfaces. Especifica\xe7\xf5es detalhadas de hardware, desenhos mec\xe2nicos e recursos t\xe9cnicos s\xe3o fornecidos para desenvolvedores, juntamente com canais de suporte t\xe9cnico e comunidade para solu\xe7\xe3o de problemas e discuss\xe3o.","permalink":"/pt-br/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/pt_reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Desempenho de IA de Pr\xf3xima Gera\xe7\xe3o em Infer\xeancia de Borda","description":"Este artigo destaca o desempenho superior de IA do reComputer Super em compara\xe7\xe3o com o reComputer Classic, demonstrando at\xe9 1,7x de aumento na capacidade de computa\xe7\xe3o de IA com o NVIDIA Jetson Orin NX 16GB. Por meio de benchmarks pr\xe1ticos em gera\xe7\xe3o de texto com IA usando o modelo DeepSeek-R1:7B com Ollama e processamento de v\xeddeo com IA usando o modelo de detec\xe7\xe3o de objetos YOLOv11, os resultados mostram que o reComputer Super oferece velocidades de infer\xeancia significativamente mais r\xe1pidas e frequ\xeancias de GPU mais altas. Notavelmente, ele processa aproximadamente 2,37 vezes mais imagens por segundo do que o Classic. O artigo tamb\xe9m explica a import\xe2ncia de avaliar o desempenho com base no FPS reportado pelo terminal, em vez do FPS na tela, que pode ser limitado por fatores de exibi\xe7\xe3o e do sistema.","permalink":"/pt-br/recomputer_jetson_super_performance"},{"id":"Edge/NVIDIA_Jetson/Application/Computer_Vision/pt_Streaming_Vision_Agent_on_Jetson","title":"Streaming Vision Agent no Jetson","description":"Implante um Streaming Vision Agent no NVIDIA Jetson com mem\xf3ria multimodal cont\xednua dupla Qwen3-VL-2B e interface Ask ao vivo","permalink":"/pt-br/streaming_vision_agent_on_jetson"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501/pt_Hardware_Interfaces_Usage","title":"Uso das Interfaces","description":"Uso de hardware e interfaces para a placa carrier J501","permalink":"/pt-br/j501_carrier_board_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/pt_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Uso das Interfaces","description":"Este wiki fornece uma introdu\xe7\xe3o abrangente aos recursos de hardware e ao uso das interfaces da placa carrier reComputer Jetson Robotics J401. Ele abrange especifica\xe7\xf5es detalhadas, m\xf3dulos compat\xedveis, instru\xe7\xf5es de configura\xe7\xe3o e guias pr\xe1ticos para usar v\xe1rias interfaces, como expans\xe3o de c\xe2mera M.2, Ethernet, USB, CAN, UART, I2C e GMSL2, ajudando os usu\xe1rios a iniciar rapidamente o desenvolvimento de rob\xf3tica na plataforma J401.","permalink":"/pt-br/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J601/pt_Robotics_J601_carrierboard_Hardware_Interfaces_Usage","title":"Uso das Interfaces","description":"Este wiki fornece uma introdu\xe7\xe3o abrangente aos recursos de hardware e ao uso das interfaces da placa carrier reComputer Jetson Robotics J601. Ele abrange especifica\xe7\xf5es detalhadas, m\xf3dulos compat\xedveis, instru\xe7\xf5es de configura\xe7\xe3o e guias pr\xe1ticos para usar v\xe1rias interfaces, como M.2, Ethernet, USB, CAN, RS485/RS232, UART, I2C, I2S, GPIO, expans\xe3o de c\xe2mera GMSL2, 5G e GPS, ajudando os usu\xe1rios a iniciar rapidamente o desenvolvimento de rob\xf3tica na plataforma J601.","permalink":"/pt-br/recomputer_jetson_robotics_j601_interfaces_usage"}],"unlisted":false}}')}}]);